"use client";

import Link from "next/link";
import { motion } from "framer-motion";
import { ArrowUpRight, Clock3, Sparkles, UtensilsCrossed } from "lucide-react";
import { useLanguage } from "../i18n/LanguageProvider";

const icons = [UtensilsCrossed, Sparkles, Clock3];

export default function Contact() {
  const { t } = useLanguage();

  return (
    <section id="contact" className="relative overflow-hidden bg-[#090909] py-28 md:py-36">
      <div className="pointer-events-none absolute left-1/2 top-0 h-80 w-80 -translate-x-1/2 rounded-full bg-purple-700/10 blur-[140px]" />
      <div className="relative mx-auto w-full max-w-6xl px-8">
        <motion.div initial={{ opacity: 0, y: 28 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, amount: 0.2 }} transition={{ duration: 0.65 }} className="mx-auto max-w-3xl text-center">
          <p className="text-sm uppercase tracking-[0.55em] text-purple-400">{t.contact.eyebrow}</p>
          <h2 className="mt-6 text-5xl font-bold leading-[1.05] text-white md:text-7xl">{t.contact.title}</h2>
          <p className="mt-8 text-lg leading-9 text-zinc-400">{t.contact.copy}</p>
        </motion.div>

        <div className="mt-16 grid gap-4 md:grid-cols-3 md:gap-5">
          {t.contact.cards.map(({ title, copy, action }, index) => {
            const Icon = icons[index] ?? UtensilsCrossed;
            return (
              <motion.div key={title} initial={{ opacity: 0, y: 24 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, amount: 0.2 }} transition={{ duration: 0.55, delay: index * 0.08 }} className="group flex min-h-72 flex-col rounded-[2rem] border border-white/10 bg-[#111111] p-7 transition hover:-translate-y-1 hover:border-purple-500/40 md:p-8">
                <span className="flex h-11 w-11 items-center justify-center rounded-full border border-purple-500/30 bg-purple-500/10 text-purple-300"><Icon size={19} strokeWidth={1.7} /></span>
                <h3 className="mt-9 text-2xl font-semibold text-white">{title}</h3>
                <p className="mt-4 max-w-sm leading-7 text-zinc-400">{copy}</p>
                <Link href="#reservation" className="mt-auto inline-flex items-center gap-2 pt-8 text-xs font-medium uppercase tracking-[0.22em] text-white transition group-hover:text-purple-300">
                  {action}
                  <ArrowUpRight size={16} className="transition group-hover:-translate-y-0.5 group-hover:translate-x-0.5" />
                </Link>
              </motion.div>
            );
          })}
        </div>
      </div>
    </section>
  );
}
